refsection.programlisting:
F = gf_create_field(2, 4);
gf_to_exponential(F, [0 1 1 0])            // 5: alpha + alpha^2 = alpha^5
gf_to_exponential(F, [0 0 0 0; 0 1 1 0], "c")   // ["0"; "x^5"]
gf_to_exponential(F, F(4))'                // -1, 0, 1, ..., 14

// Back from an exponent to coefficients
F(4)(5 + 2, :)                             // [0 1 1 0]
